window.SCRIPTURE = {
 "Luke": {
  "1": {
   "26": "\nAnd in the sixth month, the angel Gabriel was sent from God into a city of Galilee, called Nazareth,",
   "27": "\nTo a virgin espoused to a man whose name was Joseph, of the house of David: and the virgin's name was Mary.",
   "28": "\nAnd the angel being come in, said unto her: Hail, full of grace, the Lord is with thee: blessed art thou among women.",
   "29": "\nWho having heard, was troubled at his saying and thought with herself what manner of salutation this should be.",
   "30": "\nAnd the angel said to her: Fear not, Mary, for thou hast found grace with God.",
   "31": "\nBehold thou shalt conceive in thy womb and shalt bring forth a son: and thou shalt call his name Jesus.",
   "32": "\nHe shall be great and shall be called the Son of the Most High. And the Lord God shall give unto him the throne of David his father: and he shall reign in the house of Jacob for ever.",
   "33": "\nAnd of his kingdom there shall be no end.",
   "34": "\nAnd Mary said to the angel: How shall this be done, because I know not man?",
   "35": "\nAnd the angel answering, said to her: The Holy Ghost shall come upon thee and the power of the Most High shall overshadow thee. And therefore also the Holy which shall be born of thee shall be called the Son of God.",
   "36": "\nAnd behold thy cousin Elizabeth, she also hath conceived a son in her old age: and this is the sixth month with her that is called barren.",
   "37": "\nBecause no word shall be impossible with God.",
   "38": "\nAnd Mary said: Behold the handmaid of the Lord: be it done to me according to thy word. And the angel departed from her.",
   "39": "\nAnd Mary rising up in those days, went into the hill country with haste into a city of Juda.",
   "40": "\nAnd she entered into the house of Zachary and saluted Elizabeth.",
   "41": "\nAnd it came to pass that when Elizabeth heard the salutation of Mary, the infant leaped in her womb. And Elizabeth was filled with the Holy Ghost.",
   "42": "\nAnd she cried out with a loud voice and said: Blessed art thou among women and blessed is the fruit of thy womb.",
   "43": "\nAnd whence is this to me that the mother of my Lord should come to me?",
   "44": "\nFor behold as soon as the voice of thy salutation sounded in my ears, the infant in my womb leaped for joy.",
   "45": "\nAnd blessed art thou that hast believed, because those things shall be accomplished that were spoken to thee by the Lord.",
   "46": "\nAnd Mary said: My soul doth magnify the Lord.",
   "47": "\nAnd my spirit hath rejoiced in God my Saviour.",
   "48": "\nBecause he hath regarded the humility of his handmaid: for behold from henceforth all generations shall call me blessed.",
   "49": "\nBecause he that is mighty hath done great things to me: and holy is his name.",
   "50": "\nAnd his mercy is from generation unto generations, to them that fear him.",
   "51": "\nHe hath shewed might in his arm: he hath scattered the proud in the conceit of their heart.",
   "52": "\nHe hath put down the mighty from their seat and hath exalted the humble.",
   "53": "\nHe hath filled the hungry with good things: and the rich he hath sent empty away.",
   "54": "\nHe hath received Israel his servant, being mindful of his mercy.",
   "55": "\nAs he spoke to our fathers: to Abraham and to his seed for ever.",
   "56": "\nAnd Mary abode with her about three months. And she returned to her own house."
  },
  "2": {
   "6": "\nAnd it came to pass that when they were there, her days were accomplished that she should be delivered.",
   "7": "\nAnd she brought forth her first born son and wrapped him up in swaddling clothes and laid him in a manger: because there was no room for them in the inn.",
   "8": "\nAnd there were in the same country shepherds watching and keeping the night watches over their flock.",
   "9": "\nAnd behold an angel of the Lord stood by them and the brightness of God shone round about them: and they feared with a great fear.",
   "10": "\nAnd the angel said to them: Fear not; for, behold, I bring you good tidings of great joy that shall be to all the people:",
   "11": "\nFor, this day is born to you a Saviour, who is Christ the Lord, in the city of David.",
   "12": "\nAnd this shall be a sign unto you. You shall find the infant wrapped in swaddling clothes and laid in a manger.",
   "13": "\nAnd suddenly there was with the angel a multitude of the heavenly army, praising God and saying:",
   "14": "\nGlory to God in the highest: and on earth peace to men of good will.",
   "15": "\nAnd it came to pass, after the angels departed from them into heaven, the shepherds said one to another: Let us go over to Bethlehem and let us see this word that is come to pass, which the Lord hath shewed to us.",
   "16": "\nAnd they came with haste: and they found Mary and Joseph, and the infant lying in the manger.",
   "17": "\nAnd seeing, they understood of the word that had been spoken to them concerning this child.",
   "18": "\nAnd all that heard wondered: and at those things that were told them by the shepherds.",
   "19": "\nBut Mary kept all these words, pondering them in her heart.",
   "22": "\nAnd after the days of her purification, according to the law of Moses, were accomplished, they carried him to Jerusalem, to present him to the Lord:",
   "23": "\nAs it is written in the law of the Lord: Every male opening the womb shall be called holy to the Lord:",
   "24": "\nAnd to offer a sacrifice, according as it is written in the law of the Lord, a pair of turtledoves or two young pigeons:",
   "25": "\nAnd behold there was a man in Jerusalem named Simeon: and this man was just and devout, waiting for the consolation of Israel. And the Holy Ghost was in him.",
   "26": "\nAnd he had received an answer from the Holy Ghost, that he should not see death before he had seen the Christ of the Lord.",
   "27": "\nAnd he came by the Spirit into the temple. And when his parents brought in the child Jesus, to do for him according to the custom of the law,",
   "28": "\nHe also took him into his arms and blessed God and said",
   "29": "\nNow thou dost dismiss thy servant, O Lord, according to thy word in peace:",
   "30": "\nBecause my eyes have seen thy salvation,",
   "31": "\nWhich thou hast prepared before the face of all peoples:",
   "32": "\nA light to the revelation of the Gentiles and the glory of thy people Israel.",
   "33": "\nAnd his father and mother were wondering at those things which were spoken concerning him.",
   "34": "\nAnd Simeon blessed them and said to Mary his mother: Behold this child is set for the fall and for the resurrection of many in Israel and for a sign which shall be contradicted.",
   "35": "\nAnd thy own soul a sword shall pierce, that, out of many hearts thoughts may be revealed.",
   "36": "\nAnd there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser. She was far advanced in years and had lived with her husband seven years from her virginity.",
   "37": "\nAnd she was a widow until fourscore and four years: who departed not from the temple, by fastings and prayers serving night and day.",
   "38": "\nNow she, at the same hour, coming in, confessed to the Lord: and spoke of him to all that looked for the redemption of Israel.",
   "41": "\nAnd his parents went every year to Jerusalem, at the solemn day of the pasch.",
   "42": "\nAnd when he was twelve years old, they going up into Jerusalem, according to the custom of the feast,",
   "43": "\nAnd having fulfilled the days, when they returned, the child Jesus remained in Jerusalem. And his parents knew it not.",
   "44": "\nAnd thinking that he was in the company, they came a day's journey and sought him among their kinsfolks and acquaintance.",
   "45": "\nAnd not finding him, they returned into Jerusalem, seeking him.",
   "46": "\nAnd it came to pass, that, after three days, they found him in the temple, sitting in the midst of the doctors, hearing them and asking them questions.",
   "47": "\nAnd all that heard him were astonished at his wisdom and his answers.",
   "48": "\nAnd seeing him, they wondered. And his mother said to him: Son, why hast thou done so to us? Behold thy father and I have sought thee sorrowing.",
   "49": "\nAnd he said to them: How is it that you sought me? Did you not know that I must be about my father's business?",
   "50": "\nAnd they understood not the word that he spoke unto them.",
   "51": "\nAnd he went down with them and came to Nazareth and was subject to them. And his mother kept all these words in her heart.",
   "52": "\nAnd Jesus advanced in wisdom and age and grace with God and men."
  },
  "9": {
   "28": "\nAnd it came to pass, about eight days after these words, that he took Peter and James and John and went up into a mountain to pray.",
   "29": "\nAnd whilst he prayed, the shape of his countenance was altered and his raiment became white and glittering.",
   "30": "\nAnd behold two men were talking with him. And they were Moses and Elias,",
   "31": "\nAppearing in majesty. And they spoke of his decease that he should accomplish in Jerusalem.",
   "32": "\nBut Peter and they that were with him were heavy with sleep. And waking, they saw his glory and the two men that stood with him.",
   "33": "\nAnd it came to pass that, as they were departing from him, Peter saith to Jesus: Master, it is good for us to be here: and let us make three tabernacles, one for thee, and one for Moses; and one for Elias: not knowing what he said.",
   "34": "\nAnd as he spoke these things, there came a cloud and overshadowed them. And they were afraid when they entered into the cloud.",
   "35": "\nAnd a voice came out of the cloud; saying: This is my beloved son. Hear him.",
   "36": "\nAnd whilst the voice was uttered Jesus was found alone. And they held their peace and told no man in those days any of these things which they had seen."
  },
  "22": {
   "19": "\nAnd taking bread, he gave thanks and brake and gave to them, saying: This is my body, which is given for you. Do this for a commemoration of me.",
   "20": "\nIn like manner, the chalice also, after he had supped, saying: This is the chalice, the new testament in my blood, which shall be shed for you.",
   "39": "\nAnd going out, he went, according to his custom, to the Mount of Olives. And his disciples also followed him.",
   "40": "\nAnd when he was come to the place, he said to them: Pray, lest ye enter into temptation.",
   "41": "\nAnd he was withdrawn away from them a stone's cast. And kneeling down, he prayed.",
   "42": "\nSaying: Father, if thou wilt, remove this chalice from me: but yet not my will, but thine be done.",
   "43": "\nAnd there appeared to him an angel from heaven, strengthening him. And being in an agony, he prayed the longer.",
   "44": "\nAnd his sweat became as drops of blood, trickling down upon the ground.",
   "45": "\nAnd when he rose up from prayer and was come to the disciples, he found them sleeping for sorrow.",
   "46": "\nAnd he said to them: Why sleep you? Arise: pray: lest you enter into temptation."
  },
  "23": {
   "26": "\nAnd as they led him away, they laid hold of one Simon of Cyrene, coming from the country; and they laid the cross on him to carry after Jesus.",
   "27": "\nAnd there followed him a great multitude of people and of women, who bewailed and lamented him.",
   "28": "\nBut Jesus turning to them, said: Daughters of Jerusalem, weep not over me; but weep for yourselves and for your children.",
   "29": "\nFor behold, the days shall come, wherein they will say: Blessed are the barren and the wombs that have not borne and the paps that have not given suck.",
   "30": "\nThen shall they begin to say to the mountains: Fall upon us. And to the hills: Cover us.",
   "31": "\nFor if in the green wood they do these things, what shall be done in the dry?",
   "33": "\nAnd when they were come to the place which is called Calvary, they crucified him there: and the robbers, one on the right hand, and the other on the left.",
   "34": "\nAnd Jesus said: Father, forgive them, for they know not what they do. But they, dividing his garments, cast lots.",
   "35": "\nAnd the people stood beholding. And the rulers with them derided him, saying: He saved others: let him save himself, if he be Christ, the elect of God.",
   "36": "\nAnd the soldiers also mocked him, coming to him and offering him vinegar,",
   "37": "\nAnd saying: If thou be the king of the Jews, save thyself.",
   "38": "\nAnd there was also a superscription written over him in letters of Greek and Latin and Hebrew THIS IS THE KING OF THE JEWS.",
   "39": "\nAnd one of those robbers who were hanged blasphemed him, saying: If thou be Christ, save thyself and us.",
   "40": "\nBut the other answering, rebuked him, saying: Neither dost thou fear God, seeing; thou art under the same condemnation?",
   "41": "\nAnd we indeed justly: for we receive the due reward of our deeds. But this man hath done no evil.",
   "42": "\nAnd he said to Jesus: Lord, remember me when thou shalt come into thy kingdom.",
   "43": "\nAnd Jesus said to him: Amen I say to thee: This day thou shalt be with me in paradise.",
   "44": "\nAnd it was almost the sixth hour: and there was darkness over all the earth until the ninth hour.",
   "45": "\nAnd the sun was darkened, and the veil of the temple was rent in the midst.",
   "46": "\nAnd Jesus crying with a loud voice, said: Father, into thy hands I commend my spirit. And saying this, he gave up the ghost.",
   "47": "\nNow, the centurion, seeing what was done, glorified God, saying: Indeed this was a just man.",
   "48": "\nAnd all the multitude of them that were come together to that sight and saw the things that were done returned, striking their breasts.",
   "49": "\nAnd all his acquaintance and the women that had followed him from Galilee stood afar off, beholding these things."
  },
  "24": {
   "1": "\nAnd on the first day of the week, very early in the morning, they came to the sepulchre, bringing the spices which they had prepared.",
   "2": "\nAnd they found the stone rolled back from the sepulchre.",
   "3": "\nAnd going in, they found not the body of the Lord Jesus.",
   "4": "\nAnd it came to pass, as they were astonished in their mind at this, behold, two men stood by them, in shining apparel.",
   "5": "\nAnd as they were afraid and bowed down their countenance towards the ground, they said unto them: Why seek you the living with the dead?",
   "6": "\nHe is not here, but is risen. Remember how he spoke unto you, when he was yet in Galilee,",
   "7": "\nSaying: The Son of man must be delivered into the hands of sinful men and be crucified and the third day rise again.",
   "8": "\nAnd they remembered his words.",
   "50": "\nAnd he led them out as far as Bethania: and lifting up his hands, he blessed them.",
   "51": "\nAnd it came to pass, whilst he blessed them, he departed from them and was carried up to heaven.",
   "52": "\nAnd they adoring went back into Jerusalem with great joy.",
   "53": "\nAnd they were always in the temple, praising and blessing God. Amen."
  }
 },
 "Matthew": {
  "2": {
   "1": "\nWhen Jesus therefore was born in Bethlehem of Juda, in the days of king Herod, behold, there came wise men from the East to Jerusalem,",
   "2": "\nSaying: Where is he that is born king of the Jews? For we have seen his star in the East, and are come to adore him.",
   "3": "\nAnd king Herod hearing this, was troubled, and all Jerusalem with him.",
   "4": "\nAnd assembling together all the chief priests and the scribes of the people, he inquired of them where Christ should be born.",
   "5": "\nBut they said to him: In Bethlehem of Juda. For so it is written by the prophet:",
   "6": "\nAnd thou Bethlehem the land of Juda art not the least among the princes of Juda: for out of thee shall come forth the captain that shall rule my people Israel.",
   "7": "\nThen Herod, privately calling the wise men learned diligently of them the time of the star which appeared to them;",
   "8": "\nAnd sending them into Bethlehem, said: Go and diligently inquire after the child, and when you have found him, bring me word again, that I also may come and adore him.",
   "9": "\nWho having heard the king, went their way; and behold the star which they had seen in the East, went before them, until it came and stood over where the child was.",
   "10": "\nAnd seeing the star they rejoiced with exceeding great joy.",
   "11": "\nAnd entering into the house, they found the child with Mary his mother, and falling down they adored him: and opening their treasures, they offered him gifts; gold, frankincense, and myrrh."
  },
  "3": {
   "5": "\nThen went out to him Jerusalem and all Judea, and all the country about Jordan:",
   "6": "\nAnd were baptized by him in the Jordan, confessing their sins.",
   "7": "\nAnd seeing many of the Pharisees and Sadducees coming to his baptism, he said to them: Ye brood of vipers, who hath shewed you to flee from the wrath to come?",
   "8": "\nBring forth therefore fruit worthy of penance.",
   "9": "\nAnd think not to say within yourselves, We have Abraham for our father. For I tell you that God is able of these stones to raise up children to Abraham.",
   "10": "\nFor now the axe is laid to the root of the trees. Every tree therefore that doth not yield good fruit, shall be cut down, and cast into the fire.",
   "11": "\nI indeed baptize you in water unto penance, but he that shall come after me, is mightier than I, whose shoes I am not worthy to bear: he shall baptize you in the Holy Ghost and fire.",
   "12": "\nWhose fan is in his hand, and he will thoroughly cleanse his floor and gather his wheat into the barn; but the chaff he will burn with unquenchable fire.",
   "13": "\nThen cometh Jesus from Galilee to the Jordan, unto John, to be baptized by him.",
   "14": "\nBut John stayed him, saying: I ought to be baptized by thee, and comest thou to me?",
   "15": "\nAnd Jesus answering, said to him: Suffer it to be so now. For so it becometh us to fulfil all justice. Then he suffered him.",
   "16": "\nAnd Jesus being baptized, forthwith came out of the water: and lo, the heavens were opened to him: and he saw the Spirit of God descending as a dove, and coming upon him.",
   "17": "\nAnd behold a voice from heaven saying: This is my beloved Son, in whom I am well pleased."
  },
  "4": {
   "17": "\nFrom that time Jesus began to preach, and to say: Do penance, for the kingdom of heaven is at hand."
  },
  "5": {
   "1": "\nAnd seeing the multitudes, he went up into a mountain, and when he was set down, his disciples came unto him.",
   "2": "\nAnd opening his mouth he taught them, saying:",
   "3": "\nBlessed are the poor in spirit: for theirs is the kingdom of heaven.",
   "4": "\nBlessed are the meek: for they shall possess the land.",
   "5": "\nBlessed are they that mourn: for they shall be comforted.",
   "6": "\nBlessed are they that hunger and thirst after justice: for they shall have their fill.",
   "7": "\nBlessed are the merciful: for they shall obtain mercy.",
   "8": "\nBlessed are the clean of heart: they shall see God.",
   "9": "\nBlessed are the peacemakers: for they shall be called the children of God.",
   "10": "\nBlessed are they that suffer persecution for justice' sake: for theirs is the kingdom of heaven.",
   "11": "\nBlessed are ye when they shall revile you, and persecute you, and speak all that is evil against you, untruly, for my sake:",
   "12": "\nBe glad and rejoice for your reward is very great in heaven. For so they persecuted the prophets that were before you.",
   "13": "\nYou are the salt of the earth. But if the salt lose its savour, wherewith shall it be salted? It is good for nothing anymore but to be cast out, and to be trodden on by men.",
   "14": "\nYou are the light of the world. A city seated on a mountain cannot be hid.",
   "15": "\nNeither do men light a candle and put it under a bushel, but upon a candlestick, that it may shine to all that are in the house.",
   "16": "\nSo let your light shine before men, that they may see your good works, and glorify your Father who is in heaven.",
   "17": "\nDo not think that I am come to destroy the law, or the prophets. I am not come to destroy, but to fulfil.",
   "18": "\nFor amen I say unto you, till heaven and earth pass, one jot, or one tittle shall not pass of the law, till all be fulfilled.",
   "19": "\nHe therefore that shall break one of these least commandments, and shall so teach men shall be called the least in the kingdom of heaven. But he that shall do and teach, he shall be called great in the kingdom of heaven.",
   "20": "\nFor I tell you, that unless your justice abound more than that of the scribes and Pharisees, you shall not enter into the kingdom of heaven."
  },
  "10": {
   "7": "\nAnd going, preach, saying: The kingdom of heaven is at hand.",
   "8": "\nHeal the sick, raise the dead, cleanse the lepers, cast out devils: freely have you received, freely give."
  },
  "17": {
   "1": "\nAnd after six days Jesus taketh unto him Peter and James, and John his brother, and bringeth them up into a high mountain apart:",
   "2": "\nAnd he was transfigured before them. And his face did shine as the sun: and his garments became white as snow.",
   "3": "\nAnd behold there appeared to them Moses and Elias talking with him.",
   "4": "\nAnd Peter answering, said to Jesus: Lord, it is good for us to be here: if thou wilt, let us make here three tabernacles, one for thee, and one for Moses, and one for Elias.",
   "5": "\nAnd as he was yet speaking, behold a bright cloud overshadowed them. And lo a voice out of the cloud, saying: This is my beloved Son, in whom I am well pleased: hear ye him.",
   "6": "\nAnd the disciples hearing fell upon their face, and were very much afraid.",
   "7": "\nAnd Jesus came and touched them: and said to them: Arise, and fear not.",
   "8": "\nAnd they lifting up their eyes, saw no one, but only Jesus."
  },
  "26": {
   "26": "\nAnd whilst they were at supper, Jesus took bread and blessed and broke and gave to his disciples and said: Take ye and eat. This is my body.",
   "27": "\nAnd taking the chalice, he gave thanks and gave to them, saying: Drink ye all of this.",
   "28": "\nFor this is my blood of the new testament, which shall be shed for many unto remission of sins.",
   "36": "\nThen Jesus came with them into a country place which is called Gethsemani. And he said to his disciples: Sit you here, till I go yonder and pray.",
   "37": "\nAnd taking with him Peter and the two sons of Zebedee, he began to grow sorrowful and to be sad.",
   "38": "\nThen he saith to them: My soul is sorrowful even unto death. Stay you here and watch with me.",
   "39": "\nAnd going a little further, he fell upon his face, praying and saying: My Father, if it be possible, let this chalice pass from me. Nevertheless, not as I will but as thou wilt.",
   "40": "\nAnd he cometh to his disciples and findeth them asleep. And he saith to Peter: What? Could you not watch one hour with me?",
   "41": "\nWatch ye: and pray that ye enter not into temptation. The spirit indeed is willing, but the flesh is weak.",
   "42": "\nAgain the second time, he went and prayed, saying: My Father, if this chalice may not pass away, but I must drink it, thy will be done.",
   "43": "\nAnd he cometh again and findeth them sleeping: for their eyes were heavy.",
   "44": "\nAnd leaving them, he went again: and he prayed the third time, saying the selfsame word.",
   "45": "\nThen he cometh to his disciples and said to them: Sleep ye now and take your rest. Behold the hour is at hand: and the Son of man shall be betrayed into the hands of sinners.",
   "46": "\nRise: let us go. Behold he is at hand that will betray me."
  },
  "27": {
   "27": "\nThen the soldiers of the governor, taking Jesus into the hall, gathered together unto him the whole band.",
   "28": "\nAnd stripping him, they put a scarlet cloak about him.",
   "29": "\nAnd platting a crown of thorns, they put it upon his head, and a reed in his right hand. And bowing the knee before him, they mocked him, saying: Hail, King of the Jews.",
   "30": "\nAnd spitting upon him, they took the reed and struck his head.",
   "33": "\nAnd they came to the place that is called Golgotha, which is the place of Calvary.",
   "34": "\nAnd they gave him wine to drink mingled with gall. And when he had tasted, he would not drink.",
   "35": "\nAnd after they had crucified him, they divided his garments, casting lots; that it might be fulfilled which was spoken by the prophet, saying: They divided my garments among them; and upon my vesture they cast lots.",
   "36": "\nAnd they sat and watched him.",
   "37": "\nAnd they put over his head his cause written: THIS IS JESUS THE KING OF THE JEWS.",
   "38": "\nThen were crucified with him two thieves: one on the right hand and one on the left.",
   "39": "\nAnd they that passed by blasphemed him, wagging their heads,",
   "40": "\nAnd saying: Vah, thou that destroyest the temple of God and in three days dost rebuild it: save thy own self. If thou be the Son of God, come down from the cross.",
   "41": "\nIn like manner also the chief priests, with the scribes and ancients, mocking said:",
   "42": "\nHe saved others: himself he cannot save. If he be the king of Israel, let him now come down from the cross: and we will believe him.",
   "43": "\nHe trusted in God: let him now deliver him if he will have him. For he said: I am the Son of God.",
   "44": "\nAnd the selfsame thing the thieves also that were crucified with him reproached him with.",
   "45": "\nNow from the sixth hour, there was darkness over the whole earth, until the ninth hour.",
   "46": "\nAnd about the ninth hour, Jesus cried with a loud voice, saying: Eli, Eli, lamma sabacthani? That is, My God, My God, why hast thou forsaken me?",
   "47": "\nAnd some that stood there and heard said: This man calleth Elias.",
   "48": "\nAnd immediately one of them running took a sponge and filled it with vinegar and put it on a reed and gave him to drink.",
   "49": "\nAnd the others said: Let be. Let us see whether Elias will come to deliver him.",
   "50": "\nAnd Jesus again crying with a loud voice, yielded up the ghost.",
   "51": "\nAnd behold the veil of the temple was rent in two from the top even to the bottom: and the earth quaked and the rocks were rent.",
   "52": "\nAnd the graves were opened: and many bodies of the saints that had slept arose,",
   "53": "\nAnd coming out of the tombs after his resurrection, came into the holy city and appeared to many.",
   "54": "\nNow the centurion and they that were with him watching Jesus, having seen the earthquake and the things that were done, were sore afraid, saying: Indeed this was the Son of God."
  },
  "28": {
   "1": "\nAnd in the end of the sabbath, when it began to dawn towards the first day of the week, came Mary Magdalen and the other Mary, to see the sepulchre.",
   "2": "\nAnd behold there was a great earthquake. For an angel of the Lord descended from heaven and coming rolled back the stone and sat upon it.",
   "3": "\nAnd his countenance was as lightning and his raiment as snow.",
   "4": "\nAnd for fear of him, the guards were struck with terror and became as dead men.",
   "5": "\nAnd the angel answering, said to the women: Fear not you: for I know that you seek Jesus who was crucified.",
   "6": "\nHe is not here. For he is risen, as he said. Come, and see the place where the Lord was laid.",
   "7": "\nAnd going quickly, tell ye his disciples that he is risen. And behold he will go before you into Galilee. There you shall see him. Lo, I have foretold it to you.",
   "8": "\nAnd they went out quickly from the sepulchre with fear and great joy, running to tell his disciples."
  }
 },
 "John": {
  "2": {
   "1": "\nAnd the third day, there was a marriage in Cana of Galilee: and the mother of Jesus was there.",
   "2": "\nAnd Jesus also was invited, and his disciples, to the marriage.",
   "3": "\nAnd the wine failing, the mother of Jesus saith to him: They have no wine.",
   "4": "\nAnd Jesus saith to her: Woman, what is that to me and to thee? My hour is not yet come.",
   "5": "\nHis mother saith to the waiters: Whatsoever he shall say to you, do ye.",
   "6": "\nNow there were set there six waterpots of stone, according to the manner of the purifying of the Jews, containing two or three measures apiece.",
   "7": "\nJesus saith to them: Fill the waterpots with water. And they filled them up to the brim.",
   "8": "\nAnd Jesus saith to them: Draw out now and carry to the chief steward of the feast. And they carried it.",
   "9": "\nAnd when the chief steward had tasted the water made wine and knew not whence it was, but the waiters knew who had drawn the water: the chief steward calleth the bridegroom,",
   "10": "\nAnd saith to him: Every man at first setteth forth good wine, and when men have well drunk, then that which is worse. But thou hast kept the good wine until now.",
   "11": "\nThis beginning of miracles did Jesus in Cana of Galilee and manifested his glory. And his disciples believed in him."
  },
  "6": {
   "51": "\nI am the living bread which came down from heaven.",
   "52": "\nIf any man eat of this bread, he shall live for ever: and the bread that I will give is my flesh, for the life of the world.",
   "53": "\nThe Jews therefore strove among themselves, saying: How can this man give us his flesh to eat?",
   "54": "\nThen Jesus said to them: Amen, amen, I say unto you: except you eat the flesh of the Son of man and drink his blood, you shall not have life in you.",
   "55": "\nHe that eateth my flesh and drinketh my blood hath everlasting life: and I will raise him up in the last day.",
   "56": "\nFor my flesh is meat indeed: and my blood is drink indeed.",
   "57": "\nHe that eateth my flesh and drinketh my blood abideth in me: and I in him.",
   "58": "\nAs the living Father hath sent me and I live by the Father: so he that eateth me, the same also shall live by me.",
   "59": "\nThis is the bread that came down from heaven. Not as your fathers did eat manna and are dead. He that eateth this bread shall live for ever."
  },
  "18": {
   "36": "\nJesus answered: My kingdom is not of this world. If my kingdom were of this world, my servants would certainly strive that I should not be delivered to the Jews: but now my kingdom is not from hence.",
   "37": "\nPilate therefore said to him: Art thou a king then? Jesus answered: Thou sayest that I am a king. For this was I born, and for this came I into the world; that I should give testimony to the truth. Every one that is of the truth heareth my voice.",
   "38": "\nPilate saith to him: What is truth? And when he said this, he went out again to the Jews and saith to them: I find no cause in him."
  },
  "19": {
   "1": "\nThen therefore Pilate took Jesus and scourged him.",
   "2": "\nAnd the soldiers platting a crown of thorns, put it upon his head: and they put on him a purple garment.",
   "3": "\nAnd they came to him and said: Hail, king of the Jews. And they gave him blows.",
   "4": "\nPilate therefore went forth again and saith to them: Behold, I bring him forth unto you, that you may know that I find no cause in him.",
   "5": "\n(Jesus therefore came forth, bearing the crown of thorns and the purple garment.) And he saith to them: Behold the Man.",
   "17": "\nAnd bearing his own cross, he went forth to the place which is called Calvary, but in Hebrew Golgotha."
  }
 },
 "1 Corinthians": {
  "11": {
   "23": "\nFor I have received of the Lord that which also I delivered unto you, that the Lord Jesus, the same night in which he was betrayed, took bread,",
   "24": "\nAnd giving thanks, broke and said: Take ye and eat: This is my body, which shall be delivered for you. This do for the commemoration of me.",
   "25": "\nIn like manner also the chalice, after he had supped, saying: This chalice is the new testament in my blood. This do ye, as often as you shall drink, for the commemoration of me.",
   "26": "\nFor as often as you shall eat this bread and drink the chalice, you shall shew the death of the Lord, until he come.",
   "27": "\nTherefore, whosoever shall eat this bread, or drink the chalice of the Lord unworthily, shall be guilty of the body and of the blood of the Lord.",
   "28": "\nBut let a man prove himself: and so let him eat of that bread and drink of the chalice.",
   "29": "\nFor he that eateth and drinketh unworthily eateth and drinketh judgment to himself, not discerning the body of the Lord."
  }
 },
 "Isaiah": {
  "53": {
   "3": "\nDespised, and the most abject of men, a man of sorrows, and acquainted with infirmity: and his look was as it were hidden and despised, whereupon we esteemed him not.",
   "4": "\nSurely he hath borne our infirmities and carried our sorrows: and we have thought him as it were a leper, and as one struck by God and afflicted.",
   "5": "\nBut he was wounded for our iniquities, he was bruised for our sins: the chastisement of our peace was upon him, and by his bruises we are healed.",
   "6": "\nAll we like sheep have gone astray, every one hath turned aside into his own way: and the Lord hath laid on him the iniquity of us all.",
   "7": "\nHe was offered because it was his own will, and he opened not his mouth: he shall be led as a sheep to the slaughter, and shall be dumb as a lamb before his shearer, and he shall not open his mouth.",
   "8": "\nHe was taken away from distress, and from judgment: who shall declare his generation? because he is cut off out of the land of the living: for the wickedness of my people have I struck him."
  }
 },
 "Mark": {
  "16": {
   "6": "\nWho saith to them: Be not affrighted. you seek Jesus of Nazareth, who was crucified. He is risen: he is not here. Behold the place where they laid him.",
   "19": "\nAnd the Lord Jesus, after he had spoken to them, was taken up into heaven and sitteth on the right hand of God."
  }
 },
 "Acts": {
  "2": {
   "1": "\nAnd when the days of the Pentecost were accomplished, they were all together in one place:",
   "2": "\nAnd suddenly there came a sound from heaven, as of a mighty wind coming: and it filled the whole house where they were sitting.",
   "3": "\nAnd there appeared to them parted tongues, as it were of fire: and it sat upon every one of them.",
   "4": "\nAnd they were all filled with the Holy Ghost: and they began to speak with divers tongues, according as the Holy Ghost gave them to speak.",
   "5": "\nNow there were dwelling at Jerusalem, Jews, devout men, out of every nation under heaven.",
   "6": "\nAnd when this was noised abroad, the multitude came together, and were confounded in mind, because that every man heard them speak in his own tongue.",
   "7": "\nAnd they were all amazed, and wondered, saying: Behold, are not all these that speak Galilean?",
   "8": "\nAnd how have we heard, every man our own tongue wherein we were born?",
   "9": "\nParthians and Medes and Elamites and inhabitants of Mesopotamia, Judea, and Cappadocia, Pontus and Asia,",
   "10": "\nPhrygia and Pamphylia, Egypt and the parts of Libya about Cyrene, and strangers of Rome,",
   "11": "\nJews also, and proselytes, Cretes, and Arabians: we have heard them speak in our own tongues the wonderful works of God.",
   "12": "\nAnd they were all astonished, and wondered, saying one to another: What meaneth this?",
   "13": "\nBut others mocking, said: These men are full of new wine.",
   "26": "\nFor this my heart hath been glad, and my tongue hath rejoiced: moreover my flesh also shall rest in hope.",
   "27": "\nBecause thou wilt not leave my soul in hell: nor suffer thy Holy One to see corruption.",
   "28": "\nThou hast made known to me the ways of life: thou shalt make me full of joy with thy countenance."
  }
 },
 "Judith": {
  "15": {
   "9": "\nAnd Joachim the high priest came from Jerusalem to Bethulia with all his ancients to see Judith.",
   "10": "\nAnd when she was come out to him, they all blessed her with one voice, saying: Thou art the glory of Jerusalem, thou art the joy of Israel, thou art the honour of our people:"
  },
  "13": {
   "23": "\nAnd Ozias the prince of the people of Israel, said to her: Blessed art thou, O daughter, by the Lord the most high God, above all women upon the earth.",
   "25": "\nBecause he hath so magnified thy name this day, that thy praise shall not depart out of the mouth of men who shall be mindful of the power of the Lord for ever, for that thou hast not spared thy life, by reason of the distress and tribulation of thy people, but hast prevented our ruin in the presence of our God.",
   "31": "\nBlessed art thou by thy God in every tabernacle of Jacob, for in every nation which shall hear thy name, the God of Israel shall be magnified on occasion of thee."
  }
 },
 "Revelation": {
  "11": {
   "19": "\nAnd the temple of God was opened in heaven: and the ark of his testament was seen in his temple. And there were lightnings and voices and an earthquake and great hail."
  },
  "12": {
   "1": "\nAnd a great sign appeared in heaven: A woman clothed with the sun, and the moon under her feet, and on her head a crown of twelve stars."
  }
 },
 "Sirach": {
  "24": {
   "24": "\nI am the mother of fair love, and of fear, and of knowledge, and of holy hope.",
   "25": "\nIn me is all grace of the way and of the truth, in me is all hope of life and of virtue.",
   "26": "\nCome over to me, all ye that desire me, and be filled with my fruits.",
   "27": "\nFor my spirit is sweet above honey, and my inheritance above honey and the honeycomb."
  }
 }
};
